import heapq

def findMaxLiveThreads(service_nodes, service_from, service_to, currentValues):
    n = service_nodes
    g = [[] for _ in range(n + 1)]
    for u, v in zip(service_from, service_to):
        g[u].append(v)
        g[v].append(u)
    # low[u] = max over 已知点 k (value_k - dist(k, u))：从值大的已知点往外“下坡”传播
    NEG = float('-inf')
    low = [NEG] * (n + 1)
    h = []
    for i, v in currentValues:
        if v > low[i]:
            low[i] = v
            heapq.heappush(h, (-v, i))
    while h:
        nv, u = heapq.heappop(h)
        if -nv != low[u]:
            continue
        for w in g[u]:
            if low[u] - 1 > low[w]:
                low[w] = low[u] - 1
                heapq.heappush(h, (-low[w], w))
    # 线程数至少为 1：下界 <= 0 的点按奇偶取 1 或 2
    return [x if x >= 1 else (1 if x % 2 else 2) for x in low[1:]]
